#include "GeometryBridge.h"

#include "Kernel.h"
#include "model_core/src/ffi.rs.h"  // generated by cxx-build

namespace model {

namespace {

std::unique_ptr<Shape> wrap(TopoDS_Shape s) {
  if (s.IsNull()) return nullptr;
  return std::make_unique<Shape>(Shape{std::move(s)});
}

}  // namespace

bool shape_is_null(const Shape& shape) { return shape.value.IsNull(); }

std::unique_ptr<Shape> geom_extrude(const Profile& p, double distance) {
  switch (p.kind) {
    case ProfileKind::Rect:
      return wrap(geom::extrude(geom::RectProfile{p.width, p.height, p.x, p.y}, distance));
    case ProfileKind::Circle:
      return wrap(geom::extrude(geom::CircleProfile{p.radius, p.x, p.y}, distance));
  }
  return nullptr;
}

std::unique_ptr<Shape> geom_fuse(const Shape& a, const Shape& b) {
  return wrap(geom::fuse(a.value, b.value));
}

std::unique_ptr<Shape> geom_cut(const Shape& a, const Shape& b) {
  return wrap(geom::cut(a.value, b.value));
}

std::unique_ptr<Shape> geom_fillet_all_edges(const Shape& shape, double radius) {
  return wrap(geom::filletAllEdges(shape.value, radius));
}

namespace {

std::array<double, 3> arr(const std::array<double, 3>& a) { return a; }

geom::Loop2 toLoop(const LoopData& data) {
  geom::Loop2 loop;
  for (const SegmentData& d : data.segments) {
    geom::Seg2 s;
    switch (d.kind) {
      case SegmentKind::Arc: s.kind = geom::Seg2::Kind::Arc; break;
      case SegmentKind::Circle: s.kind = geom::Seg2::Kind::Circle; break;
      case SegmentKind::Ellipse: s.kind = geom::Seg2::Kind::Ellipse; break;
      case SegmentKind::EllipseArc: s.kind = geom::Seg2::Kind::EllipseArc; break;
      case SegmentKind::Spline: s.kind = geom::Seg2::Kind::Spline; break;
      default: s.kind = geom::Seg2::Kind::Line; break;
    }
    s.x0 = d.x0;
    s.y0 = d.y0;
    s.x1 = d.x1;
    s.y1 = d.y1;
    s.cx = d.cx;
    s.cy = d.cy;
    s.radius = d.radius;
    s.ccw = d.ccw;
    s.mx = d.mx;
    s.my = d.my;
    s.minor = d.minor;
    s.t0 = d.t0;
    s.t1 = d.t1;
    s.degree = int(d.degree);
    s.poles.assign(d.poles.begin(), d.poles.end());
    s.knots.assign(d.knots.begin(), d.knots.end());
    s.weights.assign(d.weights.begin(), d.weights.end());
    s.reversed = d.reversed;
    loop.push_back(s);
  }
  return loop;
}

}  // namespace

std::unique_ptr<Shape> geom_extrude_region(const PlaneInfo& plane, const RegionData& region, double distance) {
  geom::Plane p;
  p.origin = arr(plane.origin);
  p.xAxis = arr(plane.x_axis);
  p.yAxis = arr(plane.y_axis);
  p.normal = arr(plane.normal);
  std::vector<geom::Loop2> holes;
  for (const LoopData& h : region.holes) holes.push_back(toLoop(h));
  return wrap(geom::extrudeRegion(p, toLoop(region.outer), holes, distance));
}

}  // namespace model
